import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 변경 이력의 변경 구분 값
const CHANGE_TYPE_ADJUST = '연차 조정';
const CHANGE_TYPE_SETTLEMENT = '연차 정산';

function round2(n: number): number {
  return Math.round(n * 100) / 100;
}

@Controller('api/v1')
export class FnSfr01903Controller {
  @Post('/annual-leaves/:annualLeaveId/adjust')
  @HttpCode(200)
  async adjustAnnualLeave(@Req() req: Request) {
    const user = currentUser(req);
    user.require('근태 담당자');
    const data = checks.inputOf(req.body);
    const id = req.params['annualLeaveId'];
    if (!/^\d+$/.test(id)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '연차 ID가 올바르지 않습니다.');
    }
    const adjustDays = data['adjustDays'];
    if (typeof adjustDays !== 'number' || !Number.isFinite(adjustDays) || adjustDays === 0) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조정 일수는 0이 아닌 숫자로 입력하세요.');
    }
    const reasonRaw = data['changeReason'];
    const changeReason = typeof reasonRaw === 'string' ? reasonRaw.trim() : '';
    if (changeReason.length === 0 || changeReason.length > 500) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조정 사유를 500자 이내로 입력하세요.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT is_confirmed AS "isConfirmed", CAST(granted_days AS float8) AS "grantedDays", CAST(used_days AS float8) AS "usedDays", CAST(remaining_days AS float8) AS "remainingDays" FROM annual_leave WHERE annual_leave_id = CAST(:id AS bigint) FOR UPDATE',
        { id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'ANNUAL_LEAVE_NOT_FOUND', '연차를 찾을 수 없습니다.');
      }
      const row = rows[0];
      if (!row.isConfirmed) {
        throw new ApiError(409, 'INVALID_STATE', '확정된 연차만 조정할 수 있습니다.');
      }
      const before = row.remainingDays !== null && row.remainingDays !== undefined
        ? Number(row.remainingDays)
        : Number(row.grantedDays) - Number(row.usedDays ?? 0);
      const after = round2(before + adjustDays);
      const newGranted = round2(Number(row.grantedDays) + adjustDays);
      if (after < 0 || newGranted < 0) {
        throw new ApiError(422, 'REMAINING_DAYS_NEGATIVE', '조정 후 잔여 일수가 음수가 되어 조정할 수 없습니다.');
      }
      await db.execute(
        'UPDATE annual_leave SET granted_days = CAST(:granted AS numeric), remaining_days = CAST(:remaining AS numeric), updated_at = now() WHERE annual_leave_id = CAST(:id AS bigint)',
        { granted: newGranted, remaining: after, id },
      );
      // 가정: 변경 내용은 조정 전후 일수와 adjustDays를 문장으로 기록
      const content = '잔여일수 ' + round2(before) + ' -> ' + after + ' (조정 ' + adjustDays + '일)';
      await db.execute(
        'INSERT INTO change_history (changer_id, target_type, target_id, change_type, changed_at, change_content, change_reason, created_at, updated_at) VALUES (CAST(:userId AS bigint), :targetType, CAST(:id AS bigint), :changeType, now(), :content, :reason, now(), now())',
        { userId: user.id, targetType: 'annual_leave', id, changeType: CHANGE_TYPE_ADJUST, content, reason: changeReason },
      );
      return { remainingDays: after };
    });
  }

  @Post('/annual-leave-settlements')
  @HttpCode(200)
  async createAnnualLeaveSettlement(@Req() req: Request) {
    const user = currentUser(req);
    user.require('근태 담당자');
    const data = checks.inputOf(req.body);
    const leaveRaw = data['annualLeaveId'];
    if (typeof leaveRaw !== 'number' || !Number.isInteger(leaveRaw) || leaveRaw <= 0) {
      throw new ApiError(400, 'VALIDATION_FAILED', '연차를 선택하세요.');
    }
    const baseDate = data['settlementBaseDate'];
    if (typeof baseDate !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(baseDate)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '정산기준일을 YYYY-MM-DD 형식으로 입력하세요.');
    }
    return transaction(async (db) => {
      const leaves = await db.query(
        'SELECT is_confirmed AS "isConfirmed", CAST(remaining_days AS float8) AS "remainingDays" FROM annual_leave WHERE annual_leave_id = CAST(:id AS bigint) FOR UPDATE',
        { id: leaveRaw },
      );
      if (leaves.length === 0) {
        throw new ApiError(404, 'ANNUAL_LEAVE_NOT_FOUND', '연차를 찾을 수 없습니다.');
      }
      if (!leaves[0].isConfirmed) {
        throw new ApiError(409, 'INVALID_STATE', '확정된 연차만 정산할 수 있습니다.');
      }
      // 가정: 한 연차는 한 번만 정산한다 (같은 연차의 중복 수당 지급 방지)
      const exists = await db.query(
        'SELECT annual_leave_settlement_id FROM annual_leave_settlement WHERE annual_leave_id = CAST(:id AS bigint)',
        { id: leaveRaw },
      );
      if (exists.length > 0) {
        throw new ApiError(409, 'SETTLEMENT_ALREADY_EXISTS', '이미 정산된 연차입니다.');
      }
      // 가정: 미사용 일수는 잔여일수 (음수면 0)
      const remaining = Number(leaves[0].remainingDays ?? 0);
      const unusedDays = remaining > 0 ? round2(remaining) : 0;
      // 가정: 수당 산출 기준(통상임금 등)이 스키마에 없어 미사용 수당은 비워 둔다
      const created = await db.query(
        'INSERT INTO annual_leave_settlement (annual_leave_id, settlement_base_date, unused_days, unused_allowance, settled_at, created_at, updated_at) VALUES (CAST(:id AS bigint), CAST(:baseDate AS date), CAST(:unusedDays AS numeric), NULL, now(), now(), now()) RETURNING annual_leave_settlement_id AS "annualLeaveSettlementId", CAST(unused_days AS float8) AS "unusedDays", CAST(unused_allowance AS float8) AS "unusedAllowance"',
        { id: leaveRaw, baseDate, unusedDays },
      );
      const result = created[0];
      await db.execute(
        'INSERT INTO change_history (changer_id, target_type, target_id, change_type, changed_at, change_content, change_reason, created_at, updated_at) VALUES (CAST(:userId AS bigint), :targetType, CAST(:targetId AS bigint), :changeType, now(), :content, NULL, now(), now())',
        {
          userId: user.id,
          targetType: 'annual_leave_settlement',
          targetId: result.annualLeaveSettlementId,
          changeType: CHANGE_TYPE_SETTLEMENT,
          content: '연차 정산 확정: 미사용 일수 ' + unusedDays,
        },
      );
      return result;
    });
  }
}

