import { useState } from 'react';
import { Badge, Band, DataTable, DateInput, Drawer, Field, Form, LookupSelect, Num, NumberInput, RefName, TextInput, call } from '../kit';
import type { PageProps, Row } from '../kit';

export default function FnSfr01903Page({ role, notify }: PageProps) {
  const [mode, setMode] = useState<'' | 'adjust' | 'settle'>('');
  const [results, setResults] = useState<Row[]>([]);
  const [annualLeaveId, setAnnualLeaveId] = useState<number | string>('');
  const [adjustDays, setAdjustDays] = useState<number | string>('');
  const [changeReason, setChangeReason] = useState('');
  const [baseDate, setBaseDate] = useState('');

  function open(next: 'adjust' | 'settle') {
    setAnnualLeaveId('');
    setAdjustDays('');
    setChangeReason('');
    setBaseDate('');
    setMode(next);
  }

  async function submitAdjust() {
    if (annualLeaveId === '') throw new Error('연차를 선택하세요.');
    if (adjustDays === '' || typeof adjustDays !== 'number') throw new Error('조정 일수를 숫자로 입력하세요.');
    if (changeReason.trim() === '') throw new Error('조정 사유를 입력하세요.');
    const res = await call('POST', '/annual-leaves/' + annualLeaveId + '/adjust', role, { adjustDays, changeReason });
    setResults([{ key: 'a' + Date.now(), kind: '조정', annualLeaveId, days: res.remainingDays, allowance: null }, ...results]);
    setMode('');
    notify('연차를 조정했습니다.');
  }

  async function submitSettle() {
    if (annualLeaveId === '') throw new Error('연차를 선택하세요.');
    if (baseDate === '') throw new Error('정산기준일을 입력하세요.');
    const res = await call('POST', '/annual-leave-settlements', role, { annualLeaveId, settlementBaseDate: baseDate });
    setResults([{ key: 's' + Date.now(), kind: '정산', annualLeaveId, days: res.unusedDays, allowance: res.unusedAllowance }, ...results]);
    setMode('');
    notify('연차 정산을 확정했습니다.');
  }

  return (
    <div>
      <h1>연차 조정 및 정산</h1>
      <Band total={results.length}>
        <button onClick={() => open('adjust')}>연차 조정</button>
        <button className="ghost" onClick={() => open('settle')}>연차 정산</button>
      </Band>
      <DataTable
        rows={results}
        empty="아직 처리한 내역이 없습니다. 위 버튼으로 연차를 조정하거나 정산해 보세요."
        columns={[
          { key: 'kind', label: '구분', render: (r) => <Badge value={r.kind} /> },
          { key: 'annualLeaveId', label: '연차', render: (r) => <RefName table="annual_leave" role={role} value={r.annualLeaveId} /> },
          { key: 'days', label: '잔여·미사용 일수', render: (r) => <Num value={r.days} /> },
          { key: 'allowance', label: '미사용 수당', render: (r) => (r.allowance === null || r.allowance === undefined ? <span>-</span> : <Num value={r.allowance} />) },
        ]}
      />
      {mode === 'adjust' && (
        <Drawer title="연차 조정" onClose={() => setMode('')}>
          <Form onSubmit={submitAdjust} submit="조정하기">
            <Field label="연차" required wide>
              <LookupSelect table="annual_leave" role={role} value={annualLeaveId} onChange={setAnnualLeaveId} />
            </Field>
            <Field label="가산(+) 또는 차감(-) 일수" required hint="차감은 음수로 입력합니다.">
              <NumberInput value={adjustDays} onChange={setAdjustDays} />
            </Field>
            <Field label="조정 사유" required wide>
              <TextInput value={changeReason} onChange={setChangeReason} multiline />
            </Field>
          </Form>
        </Drawer>
      )}
      {mode === 'settle' && (
        <Drawer title="연차 정산 확정" onClose={() => setMode('')}>
          <Form onSubmit={submitSettle} submit="정산 확정" danger note={<span>확정하면 미사용 연차가 정산되며 되돌릴 수 없습니다. 내용을 확인한 뒤 확정하세요.</span>}>
            <Field label="연차" required wide>
              <LookupSelect table="annual_leave" role={role} value={annualLeaveId} onChange={setAnnualLeaveId} />
            </Field>
            <Field label="정산기준일" required>
              <DateInput value={baseDate} onChange={setBaseDate} />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
